-- SEO meta refresh for every live SG course: 522 courses (WSQ / CASL / IBF TGS- + non-WSQ C-prefix).
--
-- Audit (2026-10-24, prod SG): metas had drifted from the course name + description, mostly after
-- repurposes (e.g. TGS-2020506075 H1 "Practical Electronics Design with Arduino" but title/description
-- still "Embedded System Integration for Robotics"). 209 stored meta_titles began with WSQ/CASL/IBF, so
-- MMD_Seotitle rendered "WSQ funded WSQ ..." (composer now emits "Funded WSQ/CASL/IBF" and strips a baked scheme word); 463 meta_descriptions ran past 160 chars.
--
-- New values, written from each course's name + short_description + description:
--   meta_title       BARE (no WSQ/CASL/IBF prefix, no brand) -- MMD_Seotitle adds "Funded WSQ"/"Funded CASL"/
--                    "Funded IBF" and "| Tertiary Courses Singapore" at render time. Primary keyword first.
--   meta_description 130-160 chars. TGS- courses end with a badge-derived funding sentence (no UTAP --
--                    outbound marketing ban); C-prefix courses carry no funding words.
--   meta_keyword     5-8 phrases, TEXT table (attribute backend_type text).
-- Store-1 overrides of the three attributes are removed so the store-0 value renders, plus the orphan
-- TEXT-table meta_description rows (mig 1212 legacy) and varchar meta_keyword rows that shadow/ignore it.
-- Product name / url_key untouched.
--
-- SG-only (store guard) -> no-op on MY/GH (C-prefix SKUs exist there too). Idempotent.
-- Post-deploy: cache flush (meta_* are not flat columns).

SET @sg := (SELECT COUNT(*) FROM core_store WHERE store_id = 1 AND code = 'singapore');
SET @a_mtitle := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 4 AND attribute_code = 'meta_title' AND backend_type = 'varchar');
SET @a_mdesc  := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 4 AND attribute_code = 'meta_description' AND backend_type = 'varchar');
SET @a_mkey   := (SELECT attribute_id FROM eav_attribute WHERE entity_type_id = 4 AND attribute_code = 'meta_keyword' AND backend_type = 'text');
SET @ok := (@sg = 1 AND @a_mtitle IS NOT NULL AND @a_mdesc IS NOT NULL AND @a_mkey IS NOT NULL);

DROP TABLE IF EXISTS mms_seo_meta_refresh_stage;

CREATE TABLE mms_seo_meta_refresh_stage (
  sku VARCHAR(64) NOT NULL PRIMARY KEY,
  mt  VARCHAR(255) NOT NULL,
  md  VARCHAR(255) NOT NULL,
  mk  TEXT NOT NULL
) DEFAULT CHARSET = utf8;


SELECT 4, @a_mtitle, 0, e.entity_id, s.mt
  FROM mms_seo_meta_refresh_stage s JOIN catalog_product_entity e ON TRIM(e.sku) = s.sku
 WHERE @ok
ON DUPLICATE KEY UPDATE value = VALUES(value);

SELECT 4, @a_mdesc, 0, e.entity_id, s.md
  FROM mms_seo_meta_refresh_stage s JOIN catalog_product_entity e ON TRIM(e.sku) = s.sku
 WHERE @ok
ON DUPLICATE KEY UPDATE value = VALUES(value);

SELECT 4, @a_mkey, 0, e.entity_id, s.mk
  FROM mms_seo_meta_refresh_stage s JOIN catalog_product_entity e ON TRIM(e.sku) = s.sku
 WHERE @ok
ON DUPLICATE KEY UPDATE value = VALUES(value);

-- store-view overrides that would shadow the new store-0 values
DELETE v FROM catalog_product_entity_varchar v
  JOIN catalog_product_entity e ON e.entity_id = v.entity_id
  JOIN mms_seo_meta_refresh_stage s ON s.sku = TRIM(e.sku)
 WHERE @ok AND v.attribute_id IN (@a_mtitle, @a_mdesc) AND v.store_id <> 0;

DELETE t FROM catalog_product_entity_text t
  JOIN catalog_product_entity e ON e.entity_id = t.entity_id
  JOIN mms_seo_meta_refresh_stage s ON s.sku = TRIM(e.sku)
 WHERE @ok AND t.attribute_id = @a_mkey AND t.store_id <> 0;

-- wrong-table orphans: meta_description in TEXT (shadows the varchar value), meta_keyword in varchar
DELETE t FROM catalog_product_entity_text t
  JOIN catalog_product_entity e ON e.entity_id = t.entity_id
  JOIN mms_seo_meta_refresh_stage s ON s.sku = TRIM(e.sku)
 WHERE @ok AND t.attribute_id = @a_mdesc;

DELETE v FROM catalog_product_entity_varchar v
  JOIN catalog_product_entity e ON e.entity_id = v.entity_id
  JOIN mms_seo_meta_refresh_stage s ON s.sku = TRIM(e.sku)
 WHERE @ok AND v.attribute_id = @a_mkey;

DROP TABLE IF EXISTS mms_seo_meta_refresh_stage;
